var resetFlag = global.get("resetFlag");
var manualSwitch = global.get("switch"); // Fetch the manual switch status

var cb_decision;
var ov_status;
var oc_status;
var xx;
var v_threshold = 250;
var c_threshold = 150;

// Debug: Log the fetched values
//node.warn("Voltage1: " + obtainV);
//node.warn("Voltage2: " + obtainV2);
//node.warn("Voltage3: " + obtainV3);
//node.warn("Current1: " + obtainI);
//node.warn("Current2: " + obtainI2);
//node.warn("Current3: " + obtainI3);
//node.warn("Reset Flag: " + resetFlag);
//node.warn("Manual Switch: " + manualSwitch);

// Check reset flag and manual switch
if (resetFlag === "0") {
    if (manualSwitch === "1") { // Switch is ON
        // Overvoltage status
        ov_status = (obtainV > v_threshold || obtainV2 > v_threshold || obtainV3 > v_threshold) ? 1 : 0;
        // Debug: Log the overvoltage status
        //node.warn("Overvoltage Status: " + ov_status);

        // Overcurrent status
        oc_status = (obtainI > c_threshold || obtainI2 > c_threshold || obtainI3 > c_threshold) ? 1 : 0;
        // Debug: Log the overcurrent status
        //node.warn("Overcurrent Status: " + oc_status);

        // Circuit breaker decision logic
        if (ov_status === 1 || oc_status === 1) {
            cb_decision = 'Open'; // Circuit breaker tripped
        } else {
            cb_decision = 'Closed'; // Circuit breaker not tripped
        }

        // Debug: Log the circuit breaker decision
        //node.warn("Circuit Breaker Decision: " + cb_decision);

        // Set global circuit breaker status
        global.set('cb_status', cb_decision);

        // Prepare message payload
        xx = cb_decision === 'Closed' ? 1 : 0; // 1 means not tripped, 0 means tripped
        msg.payload = xx;
        // Debug: Log the message payload
        //node.warn("Message Payload: " + msg.payload);
    } else { // Switch is RESET
        cb_decision = 'Open'; // Circuit breaker tripped
        global.set('cb_status', cb_decision);
        msg.payload = 0; // Indicating circuit breaker is tripped
        // Debug: Log the message payload when switch is reset
        //node.warn("Message Payload (Switch RESET): " + msg.payload);
    }
    return msg;
} else {
    msg.payload = 0;
    // Debug: Log the message payload when reset flag is not 0
    //node.warn("Message Payload (Reset Flag != 0): " + msg.payload);
    return msg;
}

